<?php require_once 'config/db.php';$id=(int)($_GET['id']??0);$q=$pdo->prepare("SELECT * FROM stories WHERE id=? AND status='published'");$q->execute([$id]);$s=$q->fetch();if(!$s){http_response_code(404);die('Story not found.');}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($s['title'])?> — DailyPost</title><link rel="stylesheet" href="assets/css/style.css"></head><body><header><a class="brand" href="index.php">Daily<span>Post</span></a><nav><a href="index.php">Read</a><a href="write.php">Write</a></nav></header><main><article class="article"><div class="art <?=htmlspecialchars($s['color'])?> big"><?=htmlspecialchars(strtoupper(substr($s['title'],0,1)))?></div><small>BY <?=htmlspecialchars(strtoupper($s['author']))?> · <?=date('M j, Y',strtotime($s['published_at']))?></small><h1><?=htmlspecialchars($s['title'])?></h1><?php if($s['excerpt']): ?><p class="lead"><?=htmlspecialchars($s['excerpt'])?></p><?php endif; ?><div class="body"><?=nl2br(htmlspecialchars($s['body']))?></div><a href="index.php">← Back to DailyPost</a></article></main></body></html>